def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return 0, 0

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def best_by_distance(items, src):
        best_item = None
        best_dist = None
        for it in items:
            if not isinstance(it, (list, tuple)) or len(it) < 2:
                continue
            p = (it[0], it[1])
            d = manhattan(src, p)
            if best_dist is None or d < best_dist:
                best_dist = d
                best_item = p
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = None
        best_dist = None
        for c in corners:
            d = manhattan(opp_pos, c)
            if best_dist is None or d > best_dist:
                best_dist = d
                target = c
        return step_toward(self_pos, target if target is not None else (sx, sy))

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "frontier_cells", "target_cells", "cells"):
            vals = observation.get(key) or []
            if isinstance(vals, (list, tuple)):
                candidates.extend(vals)
        target = best_by_distance(candidates, self_pos)
        if target is not None:
            return step_toward(self_pos, target)
        return step_away(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if isinstance(resources, (list, tuple)) and resources:
        target = best_by_distance(resources, self_pos)
        if target is not None:
            return step_toward(self_pos, target)

    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0
    if gw and gh:
        center = ((gw - 1) // 2, (gh - 1) // 2)
        if manhattan(self_pos, center) > 0:
            return step_toward(self_pos, center)

    return step_away(self_pos, opp_pos)

